<?php namespace App\Livewire\Public; use App\Models\Category; use App\Models\FoodItem; use Livewire\Attributes\Layout; use Livewire\Component; use Livewire\WithPagination; #[Layout('layouts.app')] class MenuIndex extends Component { use WithPagination; public string $search = ''; public string $categoryId = ''; public function updatedSearch(): void { $this->resetPage(); } public function updatedCategoryId(): void { $this->resetPage(); } public function render() { $items = FoodItem::with(['stall', 'category'])->where('availability', true)->whereHas('stall', fn ($q) => $q->where('status', 'active'))->when($this->search, fn ($q) => $q->where('name', 'like', '%' . $this->search . '%'))->when($this->categoryId, fn ($q) => $q->where('category_id', $this->categoryId))->paginate(9); return view('livewire.public.menu-index', ['foodItems' => $items, 'categories' => Category::all()]); } }